<?php $this->assign('title', 'Fornecedores'); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Fornecedores</h1><p class="text-body-secondary">Parceiros, prazos e condições comerciais.</p></div><?= $this->Html->link('Novo fornecedor', ['action' => 'add'], ['class' => 'btn btn-primary align-self-start']) ?></div><form class="card card-body border-0 shadow-sm mb-3"><div class="input-group"><input name="busca" value="<?= h($busca) ?>" class="form-control" placeholder="Razão social, fantasia ou CNPJ"><button class="btn btn-outline-primary">Pesquisar</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Razão social</th><th>CNPJ</th><th>Entrega</th><th>Avaliação</th><th class="text-end">Ações</th></tr></thead><tbody><?php foreach ($fornecedores as $fornecedor): ?><tr><td><?= h($fornecedor->razao_social) ?><small class="d-block text-body-secondary"><?= h($fornecedor->nome_fantasia ?: '') ?></small></td><td><?= h($fornecedor->cnpj) ?></td><td><?= h($fornecedor->prazo_medio_entrega) ?> dias</td><td><?= h($fornecedor->avaliacao ?? '-') ?></td><td class="text-end"><?= $this->Html->link('Editar', ['action' => 'edit', $fornecedor->id], ['class' => 'btn btn-sm btn-outline-primary']) ?> <?= $this->Form->postLink('Inativar', ['action' => 'inativar', $fornecedor->id], ['class' => 'btn btn-sm btn-outline-danger', 'confirm' => 'Inativar fornecedor?']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
